use std::process::ExitCode;

use callisto_graph::commands::{
    plan_publish, AlwaysRetryPolicy, PublishOptions, PublishOrchestrator, SubprocessRegistryClient, SystemTimeProvider,
};

use callisto_model::ApplyPermit;

use crate::cli::{GlobalArgs, OutputFormat, PublishArgs};
use crate::error::CliError;
use crate::output::write_report_json;
use crate::render;
use crate::runner::CliCommandRunner;
use crate::workspace::load_workspace;

/// Writes the dry-run text notice for the publish command to the given
/// writer. When the plan contains no publishable packages, emits a clear
/// "nothing to publish (dry run)" message; otherwise previews the plan.
pub(crate) fn write_dry_run_text<W: std::io::Write>(
    plan: &callisto_model::PublishPlan,
    w: &mut W,
) -> std::io::Result<()> {
    let is_empty = plan.rust_crates.is_empty()
        && plan.npm_main_packages.is_empty()
        && plan.npm_platform_packages.is_empty()
        && plan.pypi_packages.is_empty()
        && plan.releases.is_empty();
    if is_empty {
        writeln!(w, "Nothing to publish (dry run).")?;
    } else {
        writeln!(
            w,
            "Dry run: about to publish the following plan (nothing will be published):"
        )?;
        render::render_publish(plan, w)?;
    }
    Ok(())
}

/// Checks whether the environment has credentials for each ecosystem in
/// the plan. Returns human-readable warnings for any missing credentials
/// so the operator can spot auth problems before publishing; empty when
/// all required credentials are present.
///
/// `env` is injectable (pass [`std::env::var`] in production; a closure
/// in tests to avoid mutating the process environment).
///
/// Soft pre-flight check only -- doesn't fail hard. Missing credentials
/// may still let publish succeed via an alternative auth mechanism (a
/// pre-configured `.npmrc` or `~/.cargo/credentials`).
fn check_credentials(
    plan: &callisto_model::PublishPlan,
    env: impl Fn(&str) -> Result<String, std::env::VarError>,
) -> Vec<String> {
    let mut warnings = Vec::new();

    // Cargo: crates targeting the default crates.io registry need
    // CARGO_REGISTRY_TOKEN; crates targeting a named private registry need
    // CARGO_REGISTRIES_<UPPERCASE_NAME>_TOKEN. Collect the distinct variable
    // names required and warn once per missing variable.
    let mut cargo_vars_checked = std::collections::BTreeSet::new();
    for pkg in &plan.rust_crates {
        let var = match &pkg.registry {
            None => "CARGO_REGISTRY_TOKEN".to_string(),
            Some(name) => format!("CARGO_REGISTRIES_{}_TOKEN", name.to_uppercase().replace('-', "_")),
        };
        if cargo_vars_checked.insert(var.clone()) && env(&var).is_err() {
            warnings.push(format!(
                "warning: {var} is not set; cargo publish may fail authentication"
            ));
        }
    }

    if (!plan.npm_main_packages.is_empty() || !plan.npm_platform_packages.is_empty()) && env("NPM_TOKEN").is_err() {
        warnings.push("warning: NPM_TOKEN is not set; npm publish may fail authentication".to_string());
    }

    if !plan.pypi_packages.is_empty() && env("TWINE_PASSWORD").is_err() {
        warnings.push("warning: TWINE_PASSWORD is not set; twine upload may fail authentication".to_string());
    }

    warnings
}

/// Publishes every package in the workspace's publish plan to its ecosystem
/// registry (crates.io, npm, PyPI) by shelling out to that ecosystem's own
/// publisher CLI (`cargo publish`, `npm publish`, `twine upload`) — never by
/// talking to a registry's HTTP API directly.
///
/// Respects the global `--dry-run` flag: when set, this only computes and
/// prints the plan that WOULD be published (the same plan `plan-publish`
/// reports) and returns without constructing a [`PublishOrchestrator`] or
/// running any publisher command.
pub fn handle(args: PublishArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let runner = CliCommandRunner;
    let ws = load_workspace(global, &runner)?;

    let skip_publish_precheck = args.skip_publish_precheck;
    let opts = PublishOptions { only: args.only };
    let plan = plan_publish(&ws, &opts)?;

    let Some(permit) = ApplyPermit::granted_unless_dry_run(global.dry_run) else {
        match global.format {
            OutputFormat::Json => write_report_json(&mut std::io::stdout(), &plan)?,
            OutputFormat::Text => write_dry_run_text(&plan, &mut std::io::stdout())?,
        }
        return Ok(ExitCode::SUCCESS);
    };

    // Pre-flight credential check — warns before any packages are published so
    // the operator can identify missing auth tokens early.
    for warning in check_credentials(&plan, |s| std::env::var(s)) {
        eprintln!("{warning}");
    }

    let mut client = SubprocessRegistryClient::new(CliCommandRunner, ws.root.clone());
    client.load_plan(&plan);
    let format = global.format;
    let orchestrator = PublishOrchestrator::new(client, AlwaysRetryPolicy, SystemTimeProvider)
        .with_progress(move |msg| {
            crate::output::log_line(format, &msg);
        })
        .with_skip_precheck(skip_publish_precheck);
    let report = orchestrator.execute(&plan, &permit);

    match global.format {
        OutputFormat::Json => write_report_json(&mut std::io::stdout(), &report)?,
        OutputFormat::Text => render::render_publish_report(&report, &mut std::io::stdout())?,
    }

    if report.has_failures() {
        return Ok(ExitCode::FAILURE);
    }

    Ok(ExitCode::SUCCESS)
}

#[cfg(test)]
mod tests {
    use super::*;
    use callisto_model::SCHEMA_VERSION;

    fn empty_plan() -> callisto_model::PublishPlan {
        callisto_model::PublishPlan {
            schema_version: SCHEMA_VERSION,
            rust_crates: vec![],
            npm_main_packages: vec![],
            npm_platform_packages: vec![],
            pypi_packages: vec![],
            releases: vec![],
            diagnostics: vec![],
        }
    }

    // Inject a closure that always returns NotPresent — no process-environment
    // mutation needed, so these tests are safe under parallel test execution.
    fn missing_env(_var: &str) -> Result<String, std::env::VarError> {
        Err(std::env::VarError::NotPresent)
    }

    fn present_env(_var: &str) -> Result<String, std::env::VarError> {
        Ok("token".to_string())
    }

    #[test]
    fn credential_check_warns_when_npm_token_missing() {
        use callisto_model::{NpmMainPublish, RegistryKey, Version, VersionGrammar};
        use std::path::PathBuf;

        let v1 = Version::parse("1.0.0", VersionGrammar::SemVer).unwrap();
        let plan = callisto_model::PublishPlan {
            schema_version: SCHEMA_VERSION,
            rust_crates: vec![],
            npm_main_packages: vec![NpmMainPublish {
                name: "@callisto/cli".to_string(),
                version: v1,
                publish_to: RegistryKey("npm".to_string()),
                registry: None,
                tag: None,
                access: None,
                depends_on_platforms: vec![],
                package_dir: PathBuf::from("packages/callisto-cli"),
            }],
            npm_platform_packages: vec![],
            pypi_packages: vec![],
            releases: vec![],
            diagnostics: vec![],
        };

        let warnings = check_credentials(&plan, missing_env);
        assert!(
            !warnings.is_empty(),
            "expected a warning for missing NPM_TOKEN but got none"
        );
        assert!(
            warnings.iter().any(|w| w.contains("NPM_TOKEN")),
            "warning must mention NPM_TOKEN, got: {:?}",
            warnings
        );
    }

    #[test]
    fn credential_check_no_warnings_when_all_tokens_present() {
        use callisto_model::{NpmMainPublish, RegistryKey, Version, VersionGrammar};
        use std::path::PathBuf;

        let v1 = Version::parse("1.0.0", VersionGrammar::SemVer).unwrap();
        let plan = callisto_model::PublishPlan {
            schema_version: SCHEMA_VERSION,
            rust_crates: vec![],
            npm_main_packages: vec![NpmMainPublish {
                name: "@callisto/cli".to_string(),
                version: v1,
                publish_to: RegistryKey("npm".to_string()),
                registry: None,
                tag: None,
                access: None,
                depends_on_platforms: vec![],
                package_dir: PathBuf::from("packages/callisto-cli"),
            }],
            npm_platform_packages: vec![],
            pypi_packages: vec![],
            releases: vec![],
            diagnostics: vec![],
        };

        let warnings = check_credentials(&plan, present_env);
        assert!(
            warnings.is_empty(),
            "expected no warnings when all tokens present, got: {:?}",
            warnings
        );
    }

    #[test]
    fn credential_check_default_crates_io_registry_warns_on_missing_token() {
        use callisto_model::{CratePublish, RegistryKey, Version, VersionGrammar};

        let v1 = Version::parse("1.0.0", VersionGrammar::SemVer).unwrap();
        let plan = callisto_model::PublishPlan {
            schema_version: SCHEMA_VERSION,
            rust_crates: vec![CratePublish {
                name: "my-crate".to_string(),
                version: v1,
                publish_to: RegistryKey("crates-io".to_string()),
                registry: None,
                package_dir: None,
            }],
            npm_main_packages: vec![],
            npm_platform_packages: vec![],
            pypi_packages: vec![],
            releases: vec![],
            diagnostics: vec![],
        };

        let warnings = check_credentials(&plan, missing_env);
        assert!(
            warnings
                .iter()
                .any(|w| w.contains("CARGO_REGISTRY_TOKEN") && !w.contains("REGISTRIES")),
            "a crate with no named registry (crates.io) must warn about bare CARGO_REGISTRY_TOKEN, got: {:?}",
            warnings
        );
    }

    #[test]
    fn credential_check_warns_when_pypi_password_missing() {
        use callisto_model::{PypiPublish, RegistryKey, Version, VersionGrammar};
        use std::path::PathBuf;

        let v1 = Version::parse("1.0.0", VersionGrammar::SemVer).unwrap();
        let plan = callisto_model::PublishPlan {
            schema_version: SCHEMA_VERSION,
            rust_crates: vec![],
            npm_main_packages: vec![],
            npm_platform_packages: vec![],
            pypi_packages: vec![PypiPublish {
                name: "my-pkg".to_string(),
                version: v1,
                publish_to: RegistryKey("pypi".to_string()),
                package_dir: PathBuf::from("packages/my-pkg"),
                index: None,
            }],
            releases: vec![],
            diagnostics: vec![],
        };

        let warnings = check_credentials(&plan, missing_env);
        assert!(
            warnings.iter().any(|w| w.contains("TWINE_PASSWORD")),
            "expected a warning for missing TWINE_PASSWORD, got: {:?}",
            warnings
        );
    }

    #[test]
    fn handle_dry_run_text_format_succeeds_on_empty_workspace() {
        let tmp = tempfile::TempDir::new().unwrap();
        let root = tmp.path();
        std::fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = []\nresolver = \"2\"\n").unwrap();
use std::process::ExitCode;

use callisto_model::{ApplyPermit, DiagnosticSeverity, PublishPlan};

use crate::cli::{GlobalArgs, OutputFormat, TagArgs};
use crate::error::CliError;
use crate::output::write_json;
use crate::render;
use crate::runner::CliCommandRunner;
use crate::workspace::load_workspace;

pub fn handle(args: TagArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let runner = CliCommandRunner;
    let ws = load_workspace(global, &runner)?;

    // Under `--strict`, promote graph diagnostics (including crosscheck
    // failures) to Error severity and abort before creating any tags.
    if args.strict {
        let mut diags = ws.graph.diagnostics().to_vec();
        callisto_graph::commands::escalate(&mut diags, true, true);
        let has_errors = diags.iter().any(|d| d.severity == DiagnosticSeverity::Error);
        if has_errors {
            let messages: Vec<String> = diags
                .iter()
                .filter(|d| d.severity == DiagnosticSeverity::Error)
                .map(|d| d.message.clone())
                .collect();
            return Err(CliError::Other(format!(
                "--strict: workspace graph has crosscheck failures:\n{}",
                messages.join("\n")
            )));
        }
    }

    let plan_text = crate::commands::read_json_arg(&args.plan)?;

    let plan: PublishPlan =
        serde_json::from_str(&plan_text).map_err(|e| CliError::Other(format!("Failed to parse publish plan: {e}")))?;

    let opts = callisto_graph::commands::TagOptions {
        floating_major: args.floating_major,
    };
    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run);
    let report = callisto_graph::commands::create_tags_with_options(&ws, &plan, &opts, permit.as_ref())?;

    match global.format {
        OutputFormat::Json => write_json(&mut std::io::stdout(), &report)?,
        OutputFormat::Text => render::render_tag(&report, global.dry_run, &mut std::io::stdout())?,
    }

    Ok(ExitCode::SUCCESS)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// `--plan <path>` (a value that is neither `-` nor inline JSON) must be
    /// read from disk rather than treated as a literal plan or a stdin marker.
    #[test]
    fn handle_reads_plan_from_a_file_path() {
        let tmp = tempfile::TempDir::new().unwrap();
        let root = tmp.path();
        std::fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = []\nresolver = \"2\"\n").unwrap();
        std::fs::write(root.join("callisto.toml"), "").unwrap();
        drop(
            std::process::Command::new("git")
                .args(["init", "-q"])
                .current_dir(root)
                .output(),
        );

        let plan_path = root.join("plan.json");
        std::fs::write(
            &plan_path,
            serde_json::json!({
                "schemaVersion": 1,
                "rustCrates": [],
                "npmPlatformPackages": [],
                "npmMainPackages": [],
                "releases": []
            })
            .to_string(),
        )
        .unwrap();

        let global = GlobalArgs {
            format: OutputFormat::Json,
            cwd: root.to_path_buf(),
            dry_run: true,
        };

        let result = handle(
            TagArgs {
                plan: plan_path.to_string_lossy().to_string(),
                floating_major: false,
                strict: false,
            },
            &global,
        );
        assert!(result.is_ok(), "expected Ok, got: {result:?}");
        assert_eq!(result.unwrap(), ExitCode::SUCCESS);
    }

    /// `--plan <path>` for a path that does not exist must surface a
    /// `CliError::Io` naming that path, not panic or propagate a bare
    /// `std::io::Error`.
    #[test]
    fn handle_reports_io_error_for_a_nonexistent_plan_path() {
        let tmp = tempfile::TempDir::new().unwrap();
        let root = tmp.path();
        std::fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = []\nresolver = \"2\"\n").unwrap();
        std::fs::write(root.join("callisto.toml"), "").unwrap();
        drop(
            std::process::Command::new("git")
                .args(["init", "-q"])
                .current_dir(root)
                .output(),
        );

        let missing_plan = root.join("does-not-exist.json");
        let global = GlobalArgs {
            format: OutputFormat::Json,
            cwd: root.to_path_buf(),
            dry_run: true,
        };

        let result = handle(
            TagArgs {
                plan: missing_plan.to_string_lossy().to_string(),
                floating_major: false,
                strict: false,
            },
            &global,
        );
        match result {
            Err(CliError::Io { path, .. }) => {
                assert_eq!(path, Some(missing_plan));
            }
            other => panic!("expected CliError::Io, got: {other:?}"),
        }
    }
}

