use callisto_model::{ApplyPermit, CommandRunner, CreatedTag, PublishPlan, TagReport, SCHEMA_VERSION};
use callisto_vcs::{GitDataSource, VcsError};

use crate::error::GraphError;
use crate::resolver::DependencyResolver;
use crate::Workspace;

#[derive(Clone, Debug, Default)]
pub struct TagOptions {
    pub floating_major: bool,
}

pub fn create_tags<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    plan: &PublishPlan,
    permit: Option<&ApplyPermit>,
) -> Result<TagReport, GraphError> {
    create_tags_with_options(ws, plan, &TagOptions::default(), permit)
}

/// Creates one git tag per release in `plan`.
///
/// `permit` is the dry-run gate: `None` reports the tags that *would* be
/// created without touching a single ref, `Some` creates them. It replaces the
/// former `TagOptions::dry_run` bool so that the preview branch and the write
/// branch cannot disagree -- the write calls simply do not typecheck without a
/// permit in hand.
pub fn create_tags_with_options<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    plan: &PublishPlan,
    opts: &TagOptions,
    permit: Option<&ApplyPermit>,
) -> Result<TagReport, GraphError> {
    let mut tags = Vec::new();

    // `Workspace::git_access` never hard-fails on a missing gix discovery:
    // `wasm32` has no gix at all (excluded from that target's dependency
    // set), and even natively a failed discovery just means every op below
    // runs through the `CommandRunner` fallback instead. Its write
    // operations (`create_tag`/`create_floating_major`) additionally
    // guarantee a discovered repo's result is authoritative and never
    // masked by a shell retry -- see `GitAccess`'s doc comment. Sharing the
    // workspace-scoped instance (rather than a fresh `GitAccess::discover`)
    // means this command doesn't pay for a second discovery when `ws.tags()`
    // below also needs one.
    let git = ws.git_access();

    for release in &plan.releases {
        let tag_str = release.tag_name.as_str();

        let Some(permit) = permit else {
            if opts.floating_major {
                let tmpl = ws.tags()?.template(&release.package);
                if let Some(v_str) = tmpl.extract_version_str(release.tag_name.as_str()) {
                    let grammar = ws
                        .graph
                        .packages()
                        .find(|p| p.id == release.package)
                        .and_then(|p| p.version_grammar().ok())
                        .unwrap_or(callisto_model::VersionGrammar::SemVer);
                    if let Ok(ver) = callisto_model::Version::parse(v_str, grammar) {
                        if let Some(major_tag) = tmpl.render_floating_major(&ver) {
                            let major_already_existed = ws.tags()?.contains_tag(major_tag.as_str());
                            tags.push(CreatedTag {
                                package: release.package.clone(),
                                tag_name: major_tag,
                                sha: release.sha.clone(),
                                already_existed: major_already_existed,
                                is_floating_major: true,
                            });
                        }
                    }
                }
            }

            let already_existed = ws.tags()?.contains_tag(tag_str);
            let sha = if already_existed {
                match git.resolve_commit(tag_str)? {
                    Some(actual) => actual,
                    None => {
                        return Err(GraphError::Vcs(VcsError::RefNotFound {
                            ref_name: tag_str.to_string(),
                        }))
                    }
                }
            } else {
                release.sha.clone()
            };

            tags.push(CreatedTag {
                package: release.package.clone(),
                tag_name: release.tag_name.clone(),
                sha,
                already_existed,
                is_floating_major: false,
            });
            continue;
        };

        let already_existed = ws.tags()?.contains_tag(tag_str);

        let sha = if already_existed {
            match git.resolve_commit(tag_str)? {
                Some(actual) => actual,
                None => {
                    return Err(GraphError::Vcs(VcsError::RefNotFound {
                        ref_name: tag_str.to_string(),
                    }))
                }
            }
        } else {
            let msg = format!("Release {}", tag_str);
            git.create_tag(tag_str, &release.sha, Some(&msg), permit)?;
            release.sha.clone()
        };

        if opts.floating_major {
            let tmpl = ws.tags()?.template(&release.package);
            let ver_str = tmpl.extract_version_str(release.tag_name.as_str());
            let grammar = ws
                .graph
                .packages()
                .find(|p| p.id == release.package)
                .and_then(|p| p.version_grammar().ok())
                .unwrap_or(callisto_model::VersionGrammar::SemVer);

            if let Some(v_str) = ver_str {
                if let Ok(ver) = callisto_model::Version::parse(v_str, grammar) {
                    if let Some(major_tag) = tmpl.render_floating_major(&ver) {
                        let major_already_existed = ws.tags()?.contains_tag(major_tag.as_str());
                        git.create_floating_major(major_tag.as_str(), &release.sha, permit)?;
                        tags.push(CreatedTag {
                            package: release.package.clone(),
                            tag_name: major_tag,
                            sha: release.sha.clone(),
                            already_existed: major_already_existed,
                            is_floating_major: true,
                        });
                    }
                }
            }
        }

        tags.push(CreatedTag {
            package: release.package.clone(),
            tag_name: release.tag_name.clone(),
            sha,
            is_floating_major: false,
            already_existed,
        });
    }

    Ok(TagReport {
        schema_version: SCHEMA_VERSION,
        tags,
        diagnostics: Vec::new(),
    })
}
impl<R, P, T> PublishOrchestrator<R, P, T>
where
    R: RegistryClient,
    P: RateLimitPolicy,
    T: TimeProvider,
{
    pub fn new(client: R, policy: P, time: T) -> Self {
        Self {
            client,
            policy,
            time,
            progress: None,
            skip_precheck: false,
        }
    }

    /// Attach a progress callback that is invoked before each package publish
    /// attempt. The message includes the package name and version.
    pub fn with_progress<F: Fn(String) + Send + Sync + 'static>(mut self, f: F) -> Self {
        self.progress = Some(Box::new(f));
        self
    }

    /// Skips the `is_published` pre-check before every publish attempt,
    /// relying solely on the registry client's own already-published
    /// classification from the `publish()` call itself. Defaults to `false`
    /// (the pre-check runs) since some registries' `publish()` re-runs local
    /// lifecycle scripts (e.g. npm's `prepublishOnly`/`prepack`) even on an
    /// already-published version, which the pre-check avoids. Opt in when
    /// that cost matters more than the pre-check's extra registry round-trip.
    pub fn with_skip_precheck(mut self, skip: bool) -> Self {
        self.skip_precheck = skip;
        self
    }

    pub fn parse_http_429_ttl(retry_after_header: &str) -> Option<Duration> {
        parse_retry_after(retry_after_header)
    }

    fn emit_progress(&self, name: &str, version: &Version) {
        if let Some(ref cb) = self.progress {
            cb(format!("Publishing {name}@{version}…"));
        }
    }

    /// Attempts to publish every package in `plan` to its ecosystem
    /// registry, recording a per-package outcome (or failure) for each one
    /// rather than aborting the whole batch on the first error — one
    /// package's registry rejection or auth failure must not silently erase
    /// the fact that earlier packages in the same run genuinely published or
    /// were already present.
    pub fn execute(&self, plan: &PublishPlan, permit: &ApplyPermit) -> PublishReport {
        let mut attempts = Vec::new();

        for rust_crate in &plan.rust_crates {
            let pkg_id = PackageId::Prefixed {
                ecosystem: Ecosystem::Cargo,
                name: rust_crate.name.clone(),
            };
            self.emit_progress(&rust_crate.name, &rust_crate.version);
            attempts.push(self.attempt_publish(pkg_id, rust_crate.version.clone(), permit));
        }

        for npm_pkg in &plan.npm_platform_packages {
            let pkg_id = PackageId::Prefixed {
                ecosystem: Ecosystem::Npm,
                name: npm_pkg.name.clone(),
            };
            self.emit_progress(&npm_pkg.name, &npm_pkg.version);
            attempts.push(self.attempt_publish(pkg_id, npm_pkg.version.clone(), permit));
        }

        // Names of npm platform packages that did NOT successfully publish
        // above (Published/AlreadyPublished both count as success). A main
        // package declaring one of these in `depends_on_platforms` must not
        // be published: its `optionalDependencies` would reference a version
        // that was never actually uploaded. Scoped to `Ecosystem::Npm`:
        // `depends_on_platforms` is an npm-only construct, and a bare
        // `.name()` carries no ecosystem information, so an unscoped
        // comparison could mistake a same-named failed Cargo crate for a
        // failed npm platform dependency.
        let failed_platform_names: std::collections::HashSet<String> = attempts
            .iter()
            .filter(|a| a.package.ecosystem() == Some(Ecosystem::Npm) && a.result.is_failure())
            .map(|a| a.package.name().to_string())
            .collect();

        for npm_pkg in &plan.npm_main_packages {
            let pkg_id = PackageId::Prefixed {
                ecosystem: Ecosystem::Npm,
                name: npm_pkg.name.clone(),
            };
            let failed_deps: Vec<&str> = npm_pkg
                .depends_on_platforms
                .iter()
                .map(String::as_str)
                .filter(|dep| failed_platform_names.contains(*dep))
                .collect();
            if !failed_deps.is_empty() {
                attempts.push(PublishAttempt {
                    package: pkg_id,
                    version: npm_pkg.version.clone(),
                    result: PublishAttemptResult::Failed {
                        kind: "dependencyFailed".to_string(),
                        error: format!(
                            "skipped: platform dependenc{} failed to publish: {}",
                            if failed_deps.len() == 1 { "y" } else { "ies" },
                            failed_deps.join(", ")
                        ),
                    },
                });
                continue;
            }
            self.emit_progress(&npm_pkg.name, &npm_pkg.version);
            attempts.push(self.attempt_publish(pkg_id, npm_pkg.version.clone(), permit));
        }

        for pypi_pkg in &plan.pypi_packages {
            let pkg_id = PackageId::Prefixed {
                ecosystem: Ecosystem::Pypi,
                name: pypi_pkg.name.clone(),
            };
            self.emit_progress(&pypi_pkg.name, &pypi_pkg.version);
            attempts.push(self.attempt_publish(pkg_id, pypi_pkg.version.clone(), permit));
        }

        PublishReport {
            schema_version: callisto_model::SCHEMA_VERSION,
            attempts,
            diagnostics: Vec::new(),
        }
    }

    fn attempt_publish(&self, package: PackageId, version: Version, permit: &ApplyPermit) -> PublishAttempt {
        let result = match self.publish_with_retry(&package, &version, permit) {
            Ok(PublishOutcome::Published) => PublishAttemptResult::Published,
            Ok(PublishOutcome::AlreadyPublished) => PublishAttemptResult::AlreadyPublished,
            Err(err) => PublishAttemptResult::Failed {
                kind: err.kind_str().to_string(),
                error: err.to_string(),
            },
        };

        PublishAttempt {
            package,
            version,
            result,
        }
    }

    fn publish_with_retry(
        &self,
        pkg_id: &PackageId,
        version: &Version,
        permit: &ApplyPermit,
    ) -> Result<PublishOutcome, RegistryError> {
        // Treat any is_published error as "unknown — proceed to publish". The
        // pre-check is an optional optimization, not a required gate. Propagating
        // errors here aborts the publish without ever calling publish(), which
        // records a misleading failure (e.g. "rateLimited") that never reached
        // the actual publish step.
        if !self.skip_precheck && self.client.is_published(pkg_id, version).unwrap_or(false) {
            return Ok(PublishOutcome::AlreadyPublished);
        }

        let mut retries = 0usize;
        loop {
            match self.client.publish(pkg_id, version, permit) {
                // Both a fresh publish and a publish-time "already there"
                // classification are done-and-not-an-error: neither should
                // retry, and AlreadyPublished is treated identically to the
                // is_published short-circuit above.
                Ok(outcome @ (PublishOutcome::Published | PublishOutcome::AlreadyPublished)) => return Ok(outcome),
                Err(RegistryError::RateLimited(retry_after)) => {
                    if retry_after > Duration::from_secs(MAX_RETRY_AFTER_SECS) {
                        return Err(RegistryError::RateLimited(retry_after));
                    }
                    retries += 1;
                    if retries >= MAX_RATE_LIMIT_RETRIES {
                        return Err(RegistryError::Other(format!(
                            "rate-limited {MAX_RATE_LIMIT_RETRIES} consecutive times; giving up"

item.aggregated_output:
            echo "### Version Packages PR Created/Updated" >> $GITHUB_STEP_SUMMARY
            echo "$PR_BODY" >> $GITHUB_STEP_SUMMARY
          fi
          echo "::endgroup::"
        else
          echo "hasChangesets=false" >> $GITHUB_OUTPUT

          # Emit native matrix targets for downstream build jobs, deduplicated
          # by artifactName in case the same triple is declared by more than
          # one package's platform-target group. set -o pipefail ensures a
          # hard `callisto matrix` error (e.g. malformed manifest, conflicting
          # platform-target sources) fails this step instead of silently
          # producing empty output.
          set -o pipefail
          NATIVE_MATRIX=$(callisto matrix --format json | jq -c '[.platformTargets[].targets[]] | unique_by(.artifactName)') || { echo "::error::callisto matrix failed"; exit 1; }
          echo "nativeMatrix=$NATIVE_MATRIX" >> $GITHUB_OUTPUT

          echo "::group::2. Calculating Topological Publish Plan"
          PLAN_JSON=$(callisto plan-publish --format json)
          echo "$PLAN_JSON"
          echo "::endgroup::"

          # A single source of truth for "nothing to publish this run" --
          # mirrors PublishPlan::is_empty() so this can never drift from what
          # the CLI itself considers empty.
          if echo "$PLAN_JSON" | jq -e '(.rustCrates + .npmPlatformPackages + .npmMainPackages + (.pypiPackages // []) + .releases) | length == 0' > /dev/null; then
            PLAN_IS_EMPTY=true
          else
            PLAN_IS_EMPTY=false
          fi

          if [[ "$PLAN_IS_EMPTY" == "true" ]]; then
            echo "published=false" >> $GITHUB_OUTPUT
            echo "Nothing to publish this run (no changesets pending, or no package has a pending release)."
          else
          if [[ -n "$INPUT_PUBLISH" && "$INPUT_PUBLISH" != "false" ]]; then
            echo "::group::Placing Native Build Artifacts"
            while IFS=$'\t' read -r ARTIFACT DIR_RAW; do
              DIR="."
              if [[ -n "$DIR_RAW" ]]; then
                DIR="$DIR_RAW"
              fi
              mkdir -p "$DIR"
              gh run download "$GITHUB_RUN_ID" --name "$ARTIFACT" --dir "$DIR" || { echo "::error::failed to download artifact '$ARTIFACT' for placement into '$DIR' within run $GITHUB_RUN_ID"; exit 1; }
            done < <(printf '%s' "$NATIVE_MATRIX" | jq -r '.[] | [.artifactName, (.packageDir | if . == null then "null" else . end)] | @tsv')
            echo "::endgroup::"

            # Wire NPM_TOKEN into npm config so npm publish can authenticate.
            # NPM_TOKEN is forwarded explicitly in this step's env: block so it
            # is available regardless of how the caller sets it.
            if [[ -n "$NPM_TOKEN" ]]; then
              npm config set //registry.npmjs.org/:_authToken "$NPM_TOKEN"
            fi

            echo "::group::3. Executing Package Publishing"
            if [[ "$INPUT_PUBLISH" != "true" ]]; then
              echo "Executing custom publish script: $INPUT_PUBLISH"
              read -ra _publish_cmd <<< "$INPUT_PUBLISH"
              "${_publish_cmd[@]}"
              PUBLISH_EXIT=0
            else
              set +e
              REPORT_JSON=$(callisto publish --format json)
              PUBLISH_EXIT=$?
              set -e
              echo "$REPORT_JSON"
              # Narrow PLAN_JSON down to what the report confirms actually
              # published, so a single package's failure doesn't cost its
              # already-succeeded siblings a tag or a GitHub Release below.
              # Not possible for a custom publish script -- there is no
              # structured report to filter by, so PLAN_JSON is left as-is
              # in that branch (unchanged, pre-existing behaviour).
              PLAN_JSON=$(callisto filter-plan --plan "$PLAN_JSON" --report "$REPORT_JSON" --format json)
            fi
            echo "::endgroup::"

            echo "published=true" >> $GITHUB_OUTPUT
            echo "publishedPackages<<EOF" >> $GITHUB_OUTPUT
            echo "$PLAN_JSON" >> $GITHUB_OUTPUT
            echo "EOF" >> $GITHUB_OUTPUT

            if echo "$PLAN_JSON" | jq -e '(.rustCrates + .npmPlatformPackages + .npmMainPackages + (.pypiPackages // []) + .releases) | length == 0' > /dev/null; then
              echo "No packages in this run actually published successfully; skipping tag/release creation."
            else
              echo "::group::4. Tagging Release Commits & Updating Major Version Pointer Aliases"
              set +e
              TAG_REPORT_JSON=$(callisto tag --plan "$PLAN_JSON" --floating-major --format json)
              TAG_EXIT=$?
              set -e
              if [[ $TAG_EXIT -ne 0 ]]; then
                echo "::error::callisto tag failed (exit $TAG_EXIT): $TAG_REPORT_JSON"
              else
                echo "$TAG_REPORT_JSON"
                # Only the floating major-version alias (e.g. `v1`) is meant to
                # move once created -- force-pushing it is correct. An
                # immutable per-version release tag must never be force-moved;
                # pushing it plainly lets git's own non-fast-forward check
                # catch a genuine conflict instead of silently overwriting it.
                IMMUTABLE_TAGS=()
                while IFS= read -r line; do
                  [[ -n "$line" ]] && IMMUTABLE_TAGS+=("$line")
                done < <(echo "$TAG_REPORT_JSON" | jq -r '.tags[] | select(.isFloatingMajor == false) | .tagName')
                FLOATING_TAGS=()
                while IFS= read -r line; do
                  [[ -n "$line" ]] && FLOATING_TAGS+=("$line")
                done < <(echo "$TAG_REPORT_JSON" | jq -r '.tags[] | select(.isFloatingMajor == true) | .tagName')

                if (( ${#IMMUTABLE_TAGS[@]} > 0 )); then
                  git push origin "${IMMUTABLE_TAGS[@]}"
                fi
                if (( ${#FLOATING_TAGS[@]} > 0 )); then
                  git push origin --force "${FLOATING_TAGS[@]}"
                fi
              fi
              echo "::endgroup::"

              if [[ "$INPUT_CREATE_GITHUB_RELEASE" == "true" ]]; then
                echo "::group::5. Creating GitHub Release Entries"
                while IFS=$'\t' read -r TAG HAS_VALID_PRERELEASE IS_PRERELEASE; do
                  [[ -z "$TAG" ]] && continue

                  if [[ "$HAS_VALID_PRERELEASE" != "true" ]]; then
                    echo "::error::release entry for tag $TAG has a missing or non-boolean isPrerelease field"
                    exit 1
                  fi

                  echo "Creating GitHub Release for tag: $TAG"

                  EXTRA_FLAGS=""
                  if [[ "$IS_PRERELEASE" == "true" ]]; then
                    EXTRA_FLAGS="--prerelease"
                  fi

                  gh release create "$TAG" --title "$TAG" --generate-notes $EXTRA_FLAGS || true
                done < <(echo "$PLAN_JSON" | jq -r '.releases[]? | [.tagName, (has("isPrerelease") and (.isPrerelease|type=="boolean")), (.isPrerelease // false)] | @tsv')
                echo "::endgroup::"
              fi

              echo "### Packages Published Successfully" >> $GITHUB_STEP_SUMMARY
            fi

            if [[ $PUBLISH_EXIT -ne 0 ]]; then
              echo "::error::callisto publish reported one or more failures; see the report above"
              exit 1
            fi
          else
            echo "published=false" >> $GITHUB_OUTPUT
            echo "No changesets pending and no publish command provided."
          fi
          fi
        fi

